steps.code:
names=$(python3 - <<'PY'
import json
path = '/www/server/rsyncd/config.json'
try:
    data = json.load(open(path, encoding='utf-8'))
except Exception:
    data = {}
items = ((data.get('send') or {}).get('list') or [])
print('|'.join([item.get('name', '') for item in items if item.get('name')]))
PY
)
if [ -n "$names" ]; then
  python3 /www/server/jh-panel/plugins/rsyncd/index.py lsyncd_status_batch {names:"$names",status:enabled}
else
  echo "|- rsyncd 同步任务为空，跳过任务状态调整"
fi

